package com.chickencenter.ui.controllers;import com.chickencenter.model.Product;import com.chickencenter.model.Stock;import com.chickencenter.service.ProductService;import com.chickencenter.service.StockService;import com.chickencenter.util.ToastManager;import javafx.collections.FXCollections;import javafx.collections.ObservableList;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.HBox;import javafx.geometry.Pos;import java.sql.SQLException;import java.util.List;public class StockController {    @FXML private TableView<StockDisplayItem> tblStock;    @FXML private TableColumn<StockDisplayItem, Integer> colSlNo;    @FXML private TableColumn<StockDisplayItem, String> colProductName;    @FXML private TableColumn<StockDisplayItem, String> colQuantity;    @FXML private TableColumn<StockDisplayItem, Stock> colAction;        @FXML private ComboBox<Product> cmbProduct;    @FXML private TextField txtQuantity;    @FXML private Button btnAddStock;    @FXML private Button btnUpdateStock;        private final StockService stockService;    private final ProductService productService;    private final ObservableList<StockDisplayItem> stockItems;    private final ObservableList<Product> productList;    private Stock selectedStock;    public StockController() {        this.stockService = new StockService();        this.productService = new ProductService();        this.stockItems = FXCollections.observableArrayList();        this.productList = FXCollections.observableArrayList();    }    @FXML    private void initialize() {        setupTable();        loadProducts();        loadStockData();                cmbProduct.setButtonCell(new ListCell<Product>() {            protected void updateItem(Product item, boolean empty) {                super.updateItem(item, empty);                if (empty || item == null) {                    setText("Choose Product");                } else {                    setText(item.getProductName());                }            }        });                cmbProduct.setPromptText("Choose Product");    }    private void setupTable() {        tblStock.setSelectionModel(null);        tblStock.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);                        colSlNo.setCellFactory(col -> new TableCell<StockDisplayItem, Integer>() {            protected void updateItem(Integer item, boolean empty) {                super.updateItem(item, empty);                if (empty) {                    setText(null);                } else {                    setText(String.valueOf(getIndex() + 1));                }                setStyle("-fx-alignment: CENTER; -fx-font-size: 12;");            }        });                colProductName.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().productName));        colProductName.setStyle("-fx-alignment: CENTER; -fx-font-size: 12;");                colQuantity.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(String.format("%.0f", cellData.getValue().quantity)));        colQuantity.setStyle("-fx-alignment: CENTER; -fx-font-size: 12;");                colAction.setCellFactory(param -> new TableCell<StockDisplayItem, Stock>() {            private final HBox hbox = new HBox();            private final Button editBtn = new Button("Edit");            {                editBtn.setStyle("-fx-text-fill: #2563EB; -fx-font-weight: bold; -fx-cursor: hand;");                hbox.setAlignment(Pos.CENTER);                hbox.getChildren().add(editBtn);                editBtn.setOnAction(e -> {                    StockDisplayItem item = getTableView().getItems().get(getIndex());                    loadStockForEdit(item);                });            }            @Override            protected void updateItem(Stock item, boolean empty) {                super.updateItem(item, empty);                if (empty) {                    setGraphic(null);                } else {                    setGraphic(hbox);                }            }        });                tblStock.setItems(stockItems);    }    private void loadProducts() {        try {            productList.clear();            cmbProduct.getItems().clear();            var products = productService.getAllProducts();            productList.addAll(products);            cmbProduct.getItems().addAll(products);                        if (products.isEmpty()) {                cmbProduct.setPromptText("No products - add first");            } else {                cmbProduct.setPromptText("Choose Product");            }        } catch (SQLException e) {            showError("Error loading products: " + e.getMessage());        }    }        private void loadStockData() {
        try {
            stockItems.clear();
            List<Stock> stocks = stockService.getAllStock();
            
            for (Stock stock : stocks) {
                StockDisplayItem item = new StockDisplayItem();
                item.stock = stock;
                item.productId = stock.getItemId();
                item.quantity = stock.getQuantity();
                
                for (Product p : productList) {
                    if (p.getId() == stock.getItemId()) {
                        item.productName = p.getProductName();
                        break;
                    }
                }
                
                if (item.productName != null) {
                    stockItems.add(item);
                }
            }
        } catch (SQLException e) {
            showError("Error loading stock: " + e.getMessage());
        }
    }    @FXML    private void addStock() {        Product product = cmbProduct.getValue();        String qtyText = txtQuantity.getText();                if (product == null) {            showError("Please select a product");            return;        }                if (qtyText == null || qtyText.trim().isEmpty()) {            showError("Please enter quantity");            return;        }                try {            double quantity = Double.parseDouble(qtyText);            if (quantity <= 0) {                showError("Quantity must be greater than 0");                return;            }                        stockService.addStock(product.getId(), quantity);            loadStockData();            clearForm();            ToastManager.showSuccess("Stock added successfully!");                    } catch (NumberFormatException e) {            showError("Invalid quantity format");        } catch (SQLException e) {            showError("Error adding stock: " + e.getMessage());        }    }    @FXML    private void updateStock() {        if (selectedStock == null) {            showError("Please select a stock to update");            return;        }                String qtyText = txtQuantity.getText();        if (qtyText == null || qtyText.trim().isEmpty()) {            showError("Please enter quantity");            return;        }                try {            double quantity = Double.parseDouble(qtyText);            if (quantity < 0) {                showError("Quantity cannot be negative");                return;            }                        stockService.updateStock(selectedStock.getItemId(), quantity);            loadStockData();            clearForm();            ToastManager.showSuccess("Stock updated successfully!");                    } catch (NumberFormatException e) {            showError("Invalid quantity format");        } catch (SQLException e) {            showError("Error updating stock: " + e.getMessage());        }    }    @FXML    private void clearForm() {        cmbProduct.setButtonCell(new ListCell<Product>() {            protected void updateItem(Product item, boolean empty) {                super.updateItem(item, empty);                if (empty || item == null) {                    setText("Choose Product");                } else {                    setText(item.getProductName());                }            }        });                cmbProduct.getSelectionModel().clearSelection();        cmbProduct.setValue(null);        if (cmbProduct.getEditor() != null) {            cmbProduct.getEditor().clear();        }        cmbProduct.setPromptText("Choose Product");                cmbProduct.setDisable(false);        txtQuantity.clear();        selectedStock = null;        btnAddStock.setDisable(false);        btnUpdateStock.setDisable(true);    }    private void loadStockForEdit(StockDisplayItem item) {        selectedStock = item.stock;                for (Product p : productList) {            if (p.getId() == item.productId) {                cmbProduct.setValue(p);                break;            }        }                cmbProduct.setDisable(true);        txtQuantity.setText(String.format("%.0f", item.quantity));        btnAddStock.setDisable(true);        btnUpdateStock.setDisable(false);    }    private void showError(String message) {        Alert alert = new Alert(Alert.AlertType.ERROR);        alert.setTitle("Error");        alert.setHeaderText(null);        alert.setContentText(message);        alert.showAndWait();    }    public static class StockDisplayItem {        public Stock stock;        public int productId;        public String productName;        public double quantity;    }}
